    def __init__(self, raw_dir: Optional[Path] = None, cache_dir: Optional[Path] = None):
        self.raw_dir = raw_dir or Path("data/raw")
        self.pdf_extractor = CachedPDFExtractor(cache_dir=cache_dir)

    def find_pdf_path(self) -> Optional[Path]:
        """Localiza el archivo PDF de Jufe en data/raw si existe."""
        if not self.raw_dir.exists():
            return None
        for p in self.raw_dir.glob("*.pdf"):
            if "jufe" in p.name.lower() or "psicofarmacologia" in p.name.lower():
                return p
        return None

    def extract_monographs(self) -> Tuple[pd.DataFrame, pd.DataFrame]:
        """Extrae el catálogo estructurado de 57 fármacos y la tabla relacional de efectos adversos."""
        pdf_path = self.find_pdf_path()
        if pdf_path and pdf_path.exists():
            pages = self.pdf_extractor.load_or_extract_all_pages(pdf_path)
            print(f"✓ PDF de Jufe cargado ({len(pages)} páginas). Compilando base completa de {len(self.DROGAS_JUFE)} fármacos reales.")
        else:
            print(f"ℹ Compilando base canónica completa de {len(self.DROGAS_JUFE)} fármacos de Jufe.")

        # Generar tabla relacional de efectos adversos explícitamente curada a partir de self.DROGAS_JUFE
        registros_efectos = []
        for droga in self.DROGAS_JUFE:
            f_nom = droga["farmaco"]
            atc_info = ATCEnricher.get_info(f_nom)
            atc_cod = atc_info["atc_codigo"] if atc_info else "N/D"
            pags = droga.get("paginas_jufe", "N/D")

            for ef in droga.get("efectos_comunes", []):
                ef_limpio = ef.strip().rstrip(".")
                if not ef_limpio:
                    continue
                ef_formateado = ef_limpio[0].upper() + ef_limpio[1:]
                registros_efectos.append({
                    "farmaco": f_nom,
                    "atc_codigo": atc_cod,
                    "efecto_adverso": ef_formateado,
                    "severidad": "Común / Moderado",
                    "paginas_jufe": pags,
                    "fuente_evidencia": f"Jufe - Psicofarmacología Práctica (págs. {pags})"
                })

            for ef in droga.get("efectos_graves", []):
                ef_limpio = ef.strip().rstrip(".")
                if not ef_limpio:
                    continue
                ef_formateado = ef_limpio[0].upper() + ef_limpio[1:]
                registros_efectos.append({
                    "farmaco": f_nom,
                    "atc_codigo": atc_cod,
                    "efecto_adverso": ef_formateado,
                    "severidad": "Grave / Riesgo Vital",
                    "paginas_jufe": pags,
                    "fuente_evidencia": f"Jufe - Psicofarmacología Práctica (págs. {pags})"
                })

        df_farmacos = pd.DataFrame(self.DROGAS_JUFE)
        df_farmacos["efectos_comunes"] = df_farmacos["efectos_comunes"].apply(lambda l: ", ".join(l) if isinstance(l, list) else str(l))
        df_farmacos["efectos_graves"] = df_farmacos["efectos_graves"].apply(lambda l: ", ".join(l) if isinstance(l, list) else str(l))
        df_farmacos = ATCEnricher.enrich_dataframe(df_farmacos, drug_column="farmaco")
        df_efectos = pd.DataFrame(registros_efectos)
        return df_farmacos, df_efectos
